function WebSearchResultsList(props) {
  const data = (props && props.data) || {};
  const config = (props && props.config) || {};

  const BORDER = '1px solid rgba(128,128,128,.35)';
  const SOFT_BORDER = '1px solid rgba(128,128,128,.22)';

  const asString = function (v) {
    if (v === null || v === undefined) return '';
    if (typeof v === 'string') return v.trim();
    if (typeof v === 'number' || typeof v === 'boolean') return String(v);
    return '';
  };

  const asArray = function (v) {
    if (Array.isArray(v)) return v;
    if (v === null || v === undefined || v === '') return [];
    return [v];
  };

  const query = asString(data.query);

  const results = React.useMemo(function () {
    return asArray(data.results)
      .map(function (raw, i) {
        const item = raw && typeof raw === 'object' ? raw : { title: asString(raw) };
        const url = asString(item.url) || asString(item.link);
        const title = asString(item.title) || asString(item.name);
        const description = asString(item.description) || asString(item.snippet);
        const snippets = asArray(item.extra_snippets)
          .map(asString)
          .filter(function (s) { return s.length > 0; });
        return {
          index: i,
          url: url,
          title: title,
          description: description,
          snippets: snippets,
          age: asString(item.age),
          pageAge: asString(item.page_age),
          language: asString(item.language),
        };
      })
      .filter(function (r) {
        return r.url || r.title || r.description || r.snippets.length > 0;
      });
  }, [data.results]);

  const resultUrls = React.useMemo(function () {
    const seen = {};
    results.forEach(function (r) { if (r.url) seen[r.url] = true; });
    return seen;
  }, [results]);

  const urls = React.useMemo(function () {
    const out = [];
    const seen = {};
    asArray(data.urls).forEach(function (u) {
      const s = asString(u);
      if (!s || seen[s]) return;
      seen[s] = true;
      out.push(s);
    });
    return out;
  }, [data.urls]);

  const extraUrls = urls.filter(function (u) { return !resultUrls[u]; });

  const [expanded, setExpanded] = React.useState({});
  const [showLinks, setShowLinks] = React.useState(false);

  const toggle = function (key) {
    setExpanded(function (prev) {
      const next = {};
      Object.keys(prev).forEach(function (k) { next[k] = prev[k]; });
      next[key] = !prev[key];
      return next;
    });
  };

  const hostOf = function (url) {
    if (!url) return '';
    try {
      const h = new URL(url).hostname;
      return h.replace(/^www\./, '');
    } catch (e) {
      const m = String(url).replace(/^[a-z]+:\/\//i, '').split(/[/?#]/)[0];
      return (m || '').replace(/^www\./, '');
    }
  };

  const prettyUrl = function (url) {
    if (!url) return '';
    const s = String(url).replace(/^https?:\/\//i, '').replace(/\/$/, '');
    return s.length > 88 ? s.slice(0, 85) + '…' : s;
  };

  const humanizeAge = function (age, pageAge) {
    const a = asString(age);
    if (a) return a;
    const p = asString(pageAge);
    if (!p) return '';
    const t = Date.parse(p);
    if (isNaN(t)) return p;
    const diff = Date.now() - t;
    const abs = Math.abs(diff);
    const min = 60000, hour = 3600000, day = 86400000;
    const fmt = function (n, unit) {
      const r = Math.round(n);
      const label = r === 1 ? unit : unit + 's';
      return diff >= 0 ? r + ' ' + label + ' ago' : 'in ' + r + ' ' + label;
    };
    if (abs < min) return 'just now';
    if (abs < hour) return fmt(abs / min, 'minute');
    if (abs < day) return fmt(abs / hour, 'hour');
    if (abs < day * 30) return fmt(abs / day, 'day');
    if (abs < day * 365) return fmt(abs / (day * 30), 'month');
    return fmt(abs / (day * 365), 'year');
  };

  const paragraphs = function (text) {
    return String(text || '')
      .split(/\n\s*\n/)
      .map(function (p) { return p.replace(/\s+/g, ' ').trim(); })
      .filter(function (p) { return p.length > 0; });
  };

  const initialOf = function (host) {
    const h = asString(host);
    return h ? h.charAt(0).toUpperCase() : '·';
  };

  const heading = asString(config.title) || 'Web Search Results';

  const chipStyle = {
    display: 'inline-block',
    padding: '2px 8px',
    borderRadius: 999,
    border: SOFT_BORDER,
    fontSize: 11,
    lineHeight: '16px',
    opacity: 0.75,
    whiteSpace: 'nowrap',
  };

  const buttonStyle = {
    background: 'transparent',
    border: SOFT_BORDER,
    borderRadius: 6,
    color: 'currentColor',
    cursor: 'pointer',
    font: 'inherit',
    fontSize: 12,
    opacity: 0.8,
    padding: '3px 9px',
  };

  const linkStyle = { color: 'currentColor', textDecoration: 'none' };

  const empty = results.length === 0 && extraUrls.length === 0;

  return (
    <section
      style={{
        color: 'currentColor',
        background: 'transparent',
        fontFamily: 'inherit',
        fontSize: 14,
        lineHeight: 1.5,
        width: '100%',
        boxSizing: 'border-box',
      }}
    >
      <header style={{ borderBottom: BORDER, paddingBottom: 12, marginBottom: 16 }}>
        <div style={{ fontSize: 11, letterSpacing: '.08em', textTransform: 'uppercase', opacity: 0.55 }}>
          {heading}
        </div>
        <h2
          style={{
            margin: '6px 0 0',
            fontSize: 20,
            fontWeight: 650,
            lineHeight: 1.3,
            wordBreak: 'break-word',
          }}
        >
          {query ? '“' + query + '”' : 'No query recorded'}
        </h2>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginTop: 10 }}>
          <span style={chipStyle}>
            {results.length.toLocaleString()} {results.length === 1 ? 'result' : 'results'}
          </span>
          {urls.length > 0 ? (
            <span style={chipStyle}>
              {urls.length.toLocaleString()} {urls.length === 1 ? 'link' : 'links'}
            </span>
          ) : null}
        </div>
      </header>

      {empty ? (
        <p style={{ margin: 0, opacity: 0.6, fontStyle: 'italic' }}>
          This search returned no results.
        </p>
      ) : null}

      {results.length > 0 ? (
        <ol style={{ listStyle: 'none', margin: 0, padding: 0, display: 'grid', gap: 12 }}>
          {results.map(function (r) {
            const host = hostOf(r.url);
            const when = humanizeAge(r.age, r.pageAge);
            const body = paragraphs(r.description);
            const isOpen = !!expanded[r.index];
            return (
              <li
                key={r.index}
                style={{
                  border: BORDER,
                  borderRadius: 10,
                  padding: '12px 14px',
                  background: 'transparent',
                }}
              >
                <div style={{ display: 'flex', gap: 10, alignItems: 'flex-start' }}>
                  <div
                    aria-hidden="true"
                    style={{
                      flex: '0 0 auto',
                      width: 26,
                      height: 26,
                      borderRadius: 6,
                      border: SOFT_BORDER,
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      fontSize: 12,
                      fontWeight: 700,
                      opacity: 0.7,
                    }}
                  >
                    {initialOf(host)}
                  </div>
                  <div style={{ minWidth: 0, flex: '1 1 auto' }}>
                    <div style={{ display: 'flex', gap: 8, alignItems: 'baseline', flexWrap: 'wrap' }}>
                      <span style={{ fontSize: 11, opacity: 0.5, fontVariantNumeric: 'tabular-nums' }}>
                        {(r.index + 1).toLocaleString()}
                      </span>
                      <h3 style={{ margin: 0, fontSize: 15, fontWeight: 640, lineHeight: 1.35, wordBreak: 'break-word' }}>
                        {r.url ? (
                          <a
                            href={r.url}
                            target="_blank"
                            rel="noopener noreferrer"
                            style={{ ...linkStyle, borderBottom: '1px solid rgba(128,128,128,.45)' }}
                          >
                            {r.title || prettyUrl(r.url)}
                          </a>
                        ) : (
                          r.title || 'Untitled result'
                        )}
                      </h3>
                    </div>

                    {r.url ? (
                      <div style={{ marginTop: 3, fontSize: 12, opacity: 0.6, wordBreak: 'break-all' }}>
                        {host ? <strong style={{ fontWeight: 600 }}>{host}</strong> : null}
                        {host ? ' · ' : ''}
                        {prettyUrl(r.url)}
                      </div>
                    ) : null}

                    {body.length > 0 ? (
                      <div style={{ marginTop: 8 }}>
                        {body.map(function (p, i) {
                          return (
                            <p key={i} style={{ margin: i === 0 ? 0 : '8px 0 0', opacity: 0.88 }}>
                              {p}
                            </p>
                          );
                        })}
                      </div>
                    ) : null}

                    {when || r.language ? (
                      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginTop: 9 }}>
                        {when ? <span style={chipStyle}>{when}</span> : null}
                        {r.language ? <span style={chipStyle}>{r.language.toUpperCase()}</span> : null}
                      </div>
                    ) : null}

                    {r.snippets.length > 0 ? (
                      <div style={{ marginTop: 10 }}>
                        <button type="button" onClick={function () { toggle(r.index); }} style={buttonStyle}>
                          {isOpen ? 'Hide' : 'Show'} {r.snippets.length.toLocaleString()} more{' '}
                          {r.snippets.length === 1 ? 'snippet' : 'snippets'}
                        </button>
                        {isOpen ? (
                          <ul style={{ margin: '10px 0 0', paddingLeft: 18, display: 'grid', gap: 6 }}>
                            {r.snippets.map(function (s, i) {
                              return (
                                <li key={i} style={{ opacity: 0.78, fontSize: 13 }}>
                                  {s}
                                </li>
                              );
                            })}
                          </ul>
                        ) : null}
                      </div>
                    ) : null}
                  </div>
                </div>
              </li>
            );
          })}
        </ol>
      ) : null}

      {urls.length > 0 ? (
        <div style={{ marginTop: 18, borderTop: BORDER, paddingTop: 12 }}>
          <button type="button" onClick={function () { setShowLinks(!showLinks); }} style={buttonStyle}>
            {showLinks ? 'Hide' : 'Show'} all {urls.length.toLocaleString()}{' '}
            {urls.length === 1 ? 'link' : 'links'}
          </button>
          {showLinks ? (
            <ol style={{ margin: '10px 0 0', paddingLeft: 20, display: 'grid', gap: 5 }}>
              {urls.map(function (u, i) {
                return (
                  <li key={i} style={{ fontSize: 13, wordBreak: 'break-all' }}>
                    <a
                      href={u}
                      target="_blank"
                      rel="noopener noreferrer"
                      style={{ ...linkStyle, opacity: 0.85, borderBottom: '1px solid rgba(128,128,128,.3)' }}
                    >
                      {prettyUrl(u)}
                    </a>
                  </li>
                );
              })}
            </ol>
          ) : null}
        </div>
      ) : null}
    </section>
  );
}
